31		<style>
32			:root {
33				color-scheme: light dark;
34				--text: #1a1a1a;
35				--text-secondary: #555;
36				--background: #fff;
37				--accent: #0052a3;
38				--border: #e0e0e0;
39			}
40			@media (prefers-color-scheme: dark) {
41				:root {
42					--text: #e0e0e0;
43					--text-secondary: #a0a0a0;
44					--background: #121212;
45					--accent: #5fa3ff;
46					--border: #333;
47				}
48			}
49			*,
50			*::before,
51			*::after {
52				box-sizing: border-box;
53			}
54			html {
55				-webkit-text-size-adjust: 100%;
56				text-size-adjust: 100%;
57			}
58			@media (prefers-reduced-motion: no-preference) {
59				html {
60					scroll-behavior: smooth;
61				}
62				a {
63					transition: text-decoration-thickness 0.15s ease;
64				}
65				.skip-link {
66					transition: transform 0.15s ease;
67				}
68				button {
69					transition: all 0.15s ease;
70				}
71			}
72			body {
73				display: grid;
74				grid-template-rows: auto 1fr auto;
75				min-height: 100vh;
76				min-height: 100dvh;
77				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
78				font-size: 1rem;
79				line-height: 1.6;
80				max-width: 70ch;
81				margin: 0 auto;
82				padding: clamp(1rem, 5vw, 1.5rem);
83				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
84				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
85				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
86				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
87				color: var(--text);
88				background: var(--background);
89			}
90			h1 {
91				color: var(--accent);
92				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
93				font-weight: 700;
94				line-height: 1.1;
95				text-wrap: balance;
96				margin: 0 0 1.5rem 0;
97				letter-spacing: -0.02em;
98			}
99			h2 {
100				color: var(--accent);
101				font-size: clamp(1.25rem, 1rem + 1.5vw, 1.75rem);
102				font-weight: 600;
103				line-height: 1.2;
104				text-wrap: balance;
105				margin: 2rem 0 1rem 0;
106				letter-spacing: -0.01em;
107			}
108			h2:first-child {
109				margin-top: 0;
110			}
111			p {
112				text-wrap: pretty;
113				margin: 1rem 0;
114			}
115			a {
116				color: var(--accent);
117				text-underline-offset: 0.2em;
118				text-decoration-thickness: 2px;
119				text-decoration-skip-ink: auto;
120				font-weight: 500;
121			}
122			a:hover, a:active {
123				text-decoration-thickness: 3px;
124			}
125			button {
126				padding: 0.75rem 1.5rem;
127				font-size: 1rem;
128				font-weight: 500;
129				font-family: inherit;
130				color: var(--background);
131				background: var(--accent);
132				border: 2px solid var(--accent);
133				border-radius: 0.25rem;
134				cursor: pointer;
135			}
136			button:hover {
137				opacity: 0.9;
138			}
139			button:active {
140				transform: scale(0.98);
141			}
142			ul, ol {
143				margin: 1rem 0;
144				padding-left: 2rem;
145			}
146			li {
147				margin: 0.5rem 0;
148			}
149			:focus-visible {
150				outline: 2px solid var(--accent);
151				outline-offset: 2px;
152				border-radius: 2px;
153			}
154			button:focus-visible, a:focus-visible {
155				box-shadow: 0 0 0 3px var(--background), 0 0 0 5px var(--accent);
156				outline: none;
157			}
158			.skip-link {
159				position: absolute;
160				left: 0;
161				top: 0;
162				transform: translateY(-100%);
163				background: var(--accent);
164				color: var(--background);
165				padding: 0.75rem 1.5rem;
166				z-index: 1000;
167				border-radius: 0 0 0.25rem 0;
168				font-weight: 600;
169				text-decoration: none;
170				display: inline-block;
171			}
172			.skip-link:focus {
173				transform: none;
174				outline: 3px solid var(--text);
175				outline-offset: -3px;
176			}
177			header {
178				padding-block: 1.5rem 0;
179			}
180			main {
181				padding: 1rem 0;
182			}
183			main:focus {
184				outline: none;
185			}
186			section {
187				margin: 2rem 0;
188			}
189			.card {
190				border: 1px solid var(--border);
191				border-radius: 0.5rem;
192				padding: 1.5rem;
193				background: var(--background);
194				margin: 1.5rem 0;
195			}
196			.card h3 {
197				margin-top: 0;
198				color: var(--accent);
199			}
200			footer {
201				padding-block: 1.5rem;
202				margin-top: 3rem;
203				border-top: 1px solid var(--border);
204				font-size: 0.875rem;
205				color: var(--text-secondary);
206				text-align: center;
207			}
208			footer p {
209				margin: 0.5rem 0;
210			}
211			@media print {
212				.skip-link {
213					display: none;
214				}
215				body {
216					display: block;
217					min-height: 0;
218					max-width: none;
219					padding: 0;
220				}
221				a {
222					color: inherit;
223					text-decoration: underline;
224				}
225				a[href^="http"]::after {
226					content: " (" attr(href) ")";
227					font-size: 0.85em;
228					font-weight: normal;
229				}
230				.card {
231					border: none;
232					page-break-inside: avoid;
233				}
234			}
